// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2022, "8-9", [{"author":"О. Подлесская","question":"Каким может быть студент?","choices":["новоиспечённым","свежепожаренным","слабосолёным","малосольным","недоваренным."],"key":"А","review":["Какой бывает студент","Сравни буквальные значения. «Малосольный» и «слабосолёный» говорят о продуктах, а «жареный» и «варёный» — о способе готовки.","«Новоиспечённый» в переносном смысле значит недавно получивший новое звание или положение. Так можно назвать того, кто только стал студентом."]},{"author":"Е. Муравенко","question":"Восстановите пропущенное слово в стихотворении Андрея Усачёва:\n<em>И пусть порою говорят:\nВы не Эйнштейн, и не Сократ,\nИ не Атлант в науке…\nНе верьте: если вы талант,\nНе _____ руки!</em>","choices":["<em>поднимайте</em>","<em>опускайте</em>","<em>разводите</em>","<em>зажимайте</em>","<em>убирайте</em>."],"key":"Б","review":["Руки в стихотворении","Автор призывает талантливого человека не расстраиваться и не прекращать работу из-за чужих оценок.","Устойчивое выражение «опускать руки» означает переставать действовать от уныния. В строке нужно «не опускайте руки»."]},{"author":"И. Рубанов","question":"Когда какое-то дело финансируется в последнюю очередь, то говорят, что оно <em>финансируется по _____ принципу</em>. Какое слово здесь пропущено?","choices":["<em>оставшемуся</em>","<em>останочному</em>","<em>остатковому</em>","<em>остаточному</em>","<em>достаточному</em>."],"key":"Г","review":["Деньги в последнюю очередь","Сначала средства выделяют другим делам. На это дело идут деньги, оставшиеся после основных расходов.","В таком случае говорят «финансируется по остаточному принципу». Нужное прилагательное связано со словом «остаток»."]},{"author":"Б. Иомдин","question":"У нас нет гранат. Чего у нас нет?","choices":["плодов","драгоценных камней","снарядов","плодов или снарядов","плодов, драгоценных камней или снарядов."],"key":"В","review":["Форма «гранат»","Сравни полный ряд: один гранат — нет гранатов, одна граната — нет гранат. Плоды и камни называют «гранатами», а снаряд — «гранатой».","Поскольку в условии стоит «нет гранат», во множественном числе речь о снарядах."]},{"author":"И. Наконечная","question":"В какой паре глаголы не однокоренные?","choices":["<em>прервать ― перервать</em>","<em>презреть ― перезреть</em>","<em>претерпеть ― перетерпеть</em>","<em>преломить ― переломить</em>","во всех парах представлены однокоренные глаголы."],"key":"Б","review":["Глаголы с похожим началом","«Прервать» и «перервать» связаны с «рвать». Так же обе формы с «терпеть» и обе с «ломить» имеют общие корни.","«Презреть» связано со зрением, взглядом свысока, а «перезреть» — с созреванием. Эти слова не однокоренные."]},{"author":"И. Рубанов","question":"В каком из предложений выделенное слово означает не то, что в четырёх остальных?","choices":["<em>В карету запрягли <strong>пару</strong> лошадей.</em>","<em>В семье росли трое детей: старший сын и <strong>пара</strong> близнецов.</em>","<em><strong>Пара</strong> глаз даёт человеку объёмное зрение.</em>","<em>Подождите, пожалуйста, <strong>пару</strong> минут.</em>","<em>Пролетела <strong>пара</strong> истребителей: ведущий и ведомый.</em>"],"key":"Г","review":["Что обозначает «пара»","В карету запряжены две лошади, близнецов двое, глаз два, истребителей тоже два. В этих примерах число известно точно.","«Пару минут» часто означает «несколько минут», без точного подсчёта. Здесь употребление отличается."]},{"author":"А. Сомин","question":"Какой из пяти ответов намного чаще остальных указывает на период времени?","choices":["<em>в сотых</em>","<em>в пятисотых</em>","<em>в тысячных</em>","<em>в двухтысячных</em>","<em>в миллионных</em>."],"key":"Г","review":["Название периода","Подставь «годах». Выражение «в двухтысячных» само по себе обычно понимают как часть календаря.","Оно называет годы с 2000-го по 2009-й. Остальные выражения скорее называют дробные разряды или номера и без контекста не обозначают десятилетие."]},{"author":"Л. Фёдорова","question":"Все эти прилагательные, кроме одного, описывают внешность человека. Кроме какого?","choices":["<em>краснощёкий</em>","<em>бледнолицый</em>","<em>желторотый</em>","<em>чернобровый</em>","<em>зеленоглазый</em>."],"key":"В","review":["Внешность и опыт","Щёки, лицо, брови и глаза описаны цветом. Такие прилагательные сообщают о внешности человека.","«Желторотый» буквально может быть птенец. О человеке так говорят переносно и имеют в виду молодость и неопытность."]},{"author":"С. Сай","question":"Какое предложение содержит грамматическую ошибку?","choices":["<em>Докладчик сказал с трибуны то, что все думали и так</em>.","<em>Он что-то тихонько сказал той девушке, что стояла рядом с ним</em>.","<em>Они сказали то, что это будет сюрприз</em>.","<em>Почему ты никому не сказал о том, что в сумке лежат важные документы</em>?","Все приведённые предложения грамматически правильны."],"key":"В","review":["Союз «что» в предложении","Можно сказать «сказали то, что все думали». Местоимение «то» обозначает предмет мысли, а «что» в придаточном выступает как дополнение.","Перед сообщением «это будет сюрприз» нужен только союз «что»: «Они сказали, что это будет сюрприз». Вариант В смешивает две конструкции."]},{"author":"М. Рубинштейн","question":"Маша уже умеет складывать и вычитать, но ещё не начала изучать дроби. Какую из этих задач она сможет решить?","choices":["Девочки составляют три пятых класса, а одна седьмая из них — отличницы. Сколько учащихся в классе?","Девять учеников класса ходят в бассейн. Они составляют три восьмых класса. Сколько учеников не ходят в бассейн?","В школе три пятых класса. В 5 «А» учатся 26 школьников, что на 5 меньше, чем в 5 «Б», и на 7 больше, чем в 5 «В». Сколько всего пятиклассников в этой школе?","Три седьмых класса не смогли решить задачу. В этом классе 28 человек. Сколько из них решили задачу?","Маша не сможет решить ни одну из задач (А)‒(Г)."],"key":"В","review":["Пятые классы","«Три пятых» можно понять как дробь, а можно — как число пятых классов. В варианте про 5 «А», 5 «Б» и 5 «В» речь о классах.","Из 26 учеников считаем 31 в 5 «Б» и 19 в 5 «В». Для ответа 26 + 31 + 19 = 76 достаточно сложения и вычитания."]},{"author":"С. Сай","question":"Заполните пропуск в реплике персонажа из повести О. М. Сомова «Гайдамак», опубликованной в 1825 году. <em>― Знал ли я, ждал ли я, когда он на Волыни отдавал мне для продажи пограбленные им вещи, что через три _____ увижу его здесь…?</em>","choices":["<em>звезды</em>","<em>земли</em>","<em>луны</em>","<em>планеты</em>","<em>солнца</em>."],"key":"В","review":["Как отсчитывали время","Фраза «через три» передаёт промежуток времени между встречами. В старой речи месяцы могли считать по смене фаз Луны.","«Через три луны» значит примерно через три месяца. Другие небесные тела из списка не дают такого привычного отсчёта."]},{"author":"Б. Иомдин","question":"В какой паре даны синонимы?","choices":["<em>выход — выходец</em>","<em>сыр — сырец</em>","<em>двор — дворец</em>","<em>холод</em> — <em>холодец</em>","<em>мороз — морозец</em>."],"key":"Д","review":["Близкие слова с «-ец»","Выходец — человек, сырец — необработанный продукт, дворец — здание, холодец — блюдо. Эти слова не повторяют значения парных слов.","Морозец — лёгкий мороз. Смысл остаётся тем же, добавляется уменьшительный оттенок."]},{"author":"А. Сомин","question":"От всех этих слов можно с помощью приставки и суффикса образовать прилагательные со значением ‘находящийся возле’. В каком случае произойдёт наибольшее количество чередований в основе производящего слова?","choices":["<em>дорога</em>","<em>граница</em>","<em>усадьба</em>","<em>море</em>","<em>берег</em>."],"key":"Д","review":["Прилагательные со словом «у»","Получаются «придорожный», «приграничный», «приусадебный», «приморский» и «прибрежный». Сравни в них основы исходных слов.","В паре «берег — прибрежный» одновременно выпадает первое Е и Г переходит в Ж. Это больше изменений, чем в остальных парах."]},{"author":"О. Подлесская","question":"В каком примере слово <em>узел</em> означает не то, что в других?","choices":["<em>Поставив ноги на чемодан и опираясь на мягкий узел, Ольга сидела в плетёном кресле.</em> (А. Гайдар)","<em>Растирая одеревеневшие руки и ноги, они осматривали, целы ли верёвки, не перетёрлись ли узлы, потом вставали и снова пускались в путь, прыгая, как козы, со скалы на скалу.</em> (Я. Ларри)","<em>Старик спрашивает: «Это что такое — багаж?» Я отвечаю: «Ну, узлы, чемоданы и так далее».</em> (Л. Лагин)","<em>Они были похожи на бандитов, которые, разгромив дом, тащили в узлах награбленное имущество.</em> (Я. Ларри)","<em>За ним прихрамывал храбрый Артемон с узлами на спине.</em> (А. Толстой)"],"key":"Б","review":["Два значения слова «узел»","Мягкий узел, багаж, вещи в узлах и ноша Артемона — вещи, завязанные в ткань. Во всех этих примерах слово называет свёрток.","В отрывке, где осматривают верёвки, узлы — места, в которых завязана сама верёвка. Это другое значение."]},{"author":"Е. Муравенко","question":"В какой из пар слова состоят не только из одинаковых букв, но и из одинаковых звуков?","choices":["<em>лапоть — пальто</em>","<em>шнурок — коршун</em>","<em>фирма — рифма</em>","<em>альбом — мольба</em>","<em>наказ — казна</em>."],"key":"Б","review":["Одни и те же звуки","Сверь звуки отдельно от букв: согласные могут смягчаться или оглушаться, а безударные гласные меняют произношение. Например, в «наказ» звук на конце глухой, а в «казна» звонкий.","В «шнуро́к» и «ко́ршун» одинаковы и согласные [ш], [н], [р], [к], и гласные [у] и ударный [о]. Меняется только порядок."]},{"author":"И. Рубанов","question":"Польский язык родствен русскому. Где расположен польский город Kołobrzeg (по-русски — <em>Колобжег</em>)?","choices":["в горах","среди лесов","среди полей","на границе","у моря."],"key":"Д","review":["Название польского города","Польское «koło» похоже на русское «около», а «brzeg» — на «берег». Получается название места возле берега.","Колобжег стоит на побережье Балтийского моря. Подходит «у моря»."]},{"author":"С. Дьяченко","question":"В какой паре слов наверняка пропущены разные буквы?","choices":["<em>зам_сти́ть м_стовы́е</em>","<em>прор_ди́ть р_ды́</em>","<em>учр_ди́ть о́чер_ди</em>","<em>укр_ти́ть кр_та́</em>","в каждой из пар пропущена одна и та же буква."],"key":"Б","review":["Две буквы в словосочетании","В А можно прочитать «замости́ть мостовы́е», и тогда обе буквы О. В В получаем «учреди́ть о́череди» с Е, в Г — «укроти́ть крота́» с О.","«Прореди́ть» связано с «редкий», а «ряды́» — с «ряд». Только в этой паре наверняка нужны разные буквы, Е и Я."]},{"author":"Н. Петрова","question":"Очень высокое здание по-литовски называется dangoraižis — от raižyti ‘резать, вырезать, бороздить’ и dangus, что значит _____.","choices":["‘земля’","‘небо’","‘вода’","‘огонь’","‘дерево’."],"key":"Б","review":["Литовское слово о высоте","В русском «небоскрёбе» высокое здание как будто скребёт небо. В литовском слове действие сходное: «резать, бороздить».","То, чего как будто достигает верх здания, — небо. Поэтому «dangus» означает «небо»."]},{"author":"И. Рубанов","question":"<em>X не Y, брюха не расколет</em>. В этой малоизвестной ныне русской пословице слово <em>Y</em> получается из слова <em>X</em> заменой одной буквы. А слово <em>X</em> в ней — это _____.","choices":["<em>блин</em>","<em>гриб</em>","<em>мёд</em>","<em>мука</em>","<em>хлеб</em>."],"key":"А","review":["Пословица с заменой буквы","То, что может расколоть, называют «клин». Слово из списка должно отличаться от него только первой буквой.","«Блин» отличается от «клина» одной согласной. Пословица звучит так: «Блин не клин, брюха не расколет»."]},{"author":"А. Сомин","question":"В одном юмористическом номере британский певец, находясь на гастролях в России, говорит всем окружающим по-английски, что ему нужна «окспаха». В итоге выясняется, что он искал _____.","choices":["охранника","врача","водителя","организатора концерта","уборщицу."],"key":"А","review":["Буквы на табличке","Представь русское слово, напечатанное большими буквами. Иностранец может принять их за похожие латинские знаки и прочитать по-английски.","«ОХРАНА» выглядит как «OXPAHA». Если прочитать X как «кс», P как «п», H как «х», получится «окспаха». Певцу был нужен охранник."]},{"author":"А. Пиперски","question":"<em>Всё говорит им, что Севилья\nМурильо родиной была\nИ что она такие крылья\nАртиста гению дала…</em>\n[Т. Л. Щепкина-Куперник. Марьянна Волховская (1907)]\nВыберите утверждение, которое может быть верно.","choices":["В этом тексте четыре формы именительного падежа.","В этом тексте три формы родительного падежа.","В этом тексте три формы дательного падежа.","В этом тексте три формы винительного падежа.","В этом тексте две формы творительного падежа."],"key":"В","review":["Падеж в стихотворении","«Всё говорит им» и «дала гению» содержат две формы дательного падежа. Подумай, на какой вопрос может отвечать несклоняемое имя «Мурильо».","Можно прочитать «Севилья была родиной кому? Мурильо». Тогда это третья дательная форма, и утверждение В может быть верным."]},{"author":"И. Иткин","question":"В каком из приведённых примеров, возможно, нет приставки <em>по</em>-?","choices":["<em>А пошире, чем Б</em>","<em>А поуже, чем Б</em>","<em>А подлиннее, чем Б</em>","<em>А покороче, чем Б</em>","во всех этих примерах точно есть приставка <em>по</em>-."],"key":"В","review":["Приставка или часть основы","«Пошире», «поуже» и «покороче» образованы от сравнительных форм «шире», «уже», «короче» с приставкой «по-».","«Подлиннее» может значить «длиннее» с приставкой, а может быть сравнительной формой от «подлинный» — «более настоящий». Во втором случае «по-» отдельно не выделяется."]},{"author":"И. Рубанов","question":"Вот четыре слова: 1) <em>острый</em>, 2) <em>крепкий</em>, 3) <em>сильный</em>, 4) <em>жгучий</em>. В каком порядке можно их записать, чтобы для любых двух рядом стоящих слов можно было подобрать словосочетание, не меняющее смысла при замене одного из этих слов на другое?","choices":["1, 2, 3, 4","4, 1, 2, 3","3, 4, 2, 1","1, 3, 4, 2","4, 1, 3, 2."],"key":"Д","review":["Цепочка прилагательных","«Жгучий» и «острый» можно сказать о перце, «острая» и «сильная» — о боли.","Слова «сильный» и «крепкий» сходятся в словосочетании про мороз. Получается цепочка 4, 1, 3, 2."]},{"author":"И. Рубанов","question":"Канюк — небольшая хищная птица. А его крик __________.","choices":["громок и недолог","приятен и благозвучен","надоедлив и неприятен","страшен и дик","тих и краток."],"key":"В","review":["Голос хищной птицы","Вспомни «канючить»: настойчиво просить жалобным, тягучим голосом.","По такому сравнению крик канюка можно описать как надоедливый и неприятный. Он напоминает навязчивую жалобу."]},{"author":"С. Дьяченко","question":"Какие приставки выделяются в слове <em>снизойти</em>?","choices":["<em>сн-</em>, <em>из-</em>, <em>о-</em>","<em>с-</em>, <em>низ-</em>, <em>о-</em>","<em>сн-</em>, <em>изо-</em>","<em>с-</em>, <em>низо-</em>","<em>снизо-</em>."],"key":"Г","review":["Части слова «снизойти»","Сравни «сойти» и «низойти». В одном слове к форме «йти» добавлено «со-», в другом — «низо-».","В «снизойти» перед «низойти» добавлена ещё «с-». Получаются приставки «с-» и «низо-»."]},{"author":"И. Иткин и И. Шумилова","question":"Даны пять стихотворных отрывков. Четыре из них написаны в XIX веке, один — в XX. Какой?","choices":["<em>То из-под ног мотнётся крыса, То юркнет в норку бурундук...</em>","<em>«Вон, вон отсюда!» — крикнул старший. Вдруг Исчезли все, юркнув в одно мгновенье...</em>","<em>Кольцо юркнуло в воду; Искал... но где сыскать!..</em>","<em>Мечта любви унесена, Как в тень юркнувшая волна...</em>","<em>Увы, блестящей полосой Юркнула в темноту.</em>"],"key":"А","review":["Стихи разных веков","Поищи строку, которую можно связать с автором XX века. В варианте А речь о степных животных, характерных для пейзажа из поэмы о путешествии.","Строки про крысу и бурундука взяты из поэмы Николая Заболоцкого «Рубрук в Монголии», созданной в XX веке. Это вариант А."]},{"author":"А. Сомин","question":"На столе лежат шесть словарей для перевода на русский язык: белорусско-русский и пять других. У одного из словарей русский заголовок устроен немного не так, как у остальных. Для перевода с какого языка этот словарь?","choices":["с французского","с английского","с немецкого","с арабского","с индонезийского."],"key":"Б","review":["Названия словарей","Сравни «белорусско-русский», «французско-русский», «немецко-русский», «арабско-русский» и «индонезийско-русский». В каждом случае первая часть связана с обычным прилагательным на «-ский».","Для английского закрепилось название «англо-русский», с первой частью «англо-». Оно устроено иначе."]},{"author":"А. Сомин","question":"Какое из этих слов при склонении может потерять дефис?","choices":["<em>кто-то</em>","<em>кто-нибудь</em>","<em>кое-кто</em>","<em>кто-либо</em>","ни одно из этих слов при склонении не может потерять дефис."],"key":"В","review":["Место для предлога","При склонении «кто-то», «кто-нибудь» и «кто-либо» сохраняют части после дефиса: «кого-то», «кому-нибудь», «о ком-либо».","У «кое-кто» предлог может встать между частями. Получается «кое у кого» или «кое с кем», без дефиса."]},{"author":"И. Иткин","question":"<em>бд</em>, <em>гр</em>, <em>сп</em>, <em>тл</em>... А ещё, например, ___.","choices":["<em>вз</em>","<em>йм</em>","<em>пл</em>","<em>рд</em>","<em>тв</em>."],"key":"Г","review":["Начало глагола","Добавь «-еть» к сочетаниям из условия: получатся «бдеть», «греть», «спеть», «тлеть». Все четыре — глаголы.","Из вариантов так образуется «рдеть», то есть краснеть или сиять красным. Подходит начало «рд»."]},{"author":"Б. Иомдин","question":"Есть редкий спортивный термин <em>клэб</em> — ‘клюшка для гольфа’. А со сколькими разными гласными буквами, помимо <em>э</em>, в русском языке есть слова из четырёх букв, начинающиеся на <em>кл</em>?","choices":["с пятью","с шестью","с семью","с восемью","с девятью."],"key":"Д","review":["Четыре буквы на «кл»","После «кл» подбери по слову для каждой гласной: клад, клей, клёв, клин, клоп.","Ещё получаются клуб, клык, ключ и кляп. Это девять разных гласных букв помимо Э."]}], {"year":2022,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2022-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
